import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom"; // Importando useNavigate
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfCurso = () => {
  const { id } = useParams();
  const navigate = useNavigate(); // Inicializando o navigate
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
    professor: "",
    alunos: [],
  });
  const [alunos, setAlunos] = useState([]);
  const [professores, setProfessores] = useState([]);
  const [editMode, setEditMode] = useState(false);

  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchAlunos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAlunos(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de alunos:", error);
      }
    };

    const fetchProfessores = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessores(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de professores:", error);
      }
    };

    fetchCurso();
    fetchAlunos();
    fetchProfessores();
  }, [id]);

  const handleEditClick = () => setEditMode(true);

  const handleCancelClick = () => setEditMode(false);

  const handleSaveClick = async () => {
    if (!curso) return;

    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(curso),
      });

      if (resposta.ok) {
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  const handleAlunosChange = (e) => {
    const selectedAlunos = Array.from(
      e.target.selectedOptions,
      (option) => option.value
    );
    setCurso({ ...curso, alunos: selectedAlunos });
  };

  const handleProfessorChange = (e) => {
    setCurso({ ...curso, professor: e.target.value });
  };

  if (!curso) return <p className="text-center mt-4">Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <button
            className="nav-link"
            onClick={() => navigate("/admlistcurso")}
          >
            Cursos
          </button>
        </li>
        <li className="nav-item mx-2">
          <button className="nav-link" onClick={() => navigate("/admlistprof")}>
            Professores
          </button>
        </li>
        <li className="nav-item mx-2">
          <button
            className="nav-link"
            onClick={() => navigate("/admlistaluno")}
          >
            Alunos
          </button>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informações do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>

        <div className="w-50 ps-4">
          <div className="mb-3">
            <label className="fw-bold">Professor</label>
            <div className="input-group">
              <select
                className="form-control"
                name="professor"
                value={curso.professor}
                onChange={handleProfessorChange}
                disabled={!editMode}
              >
                <option value="">Selecione um professor</option>
                {professores.map((professor) => (
                  <option key={professor.id} value={professor.nome}>
                    {professor.nome}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <label className="fw-bold">Alunos</label>
          <select
            className="form-control mb-2"
            multiple
            value={curso.alunos}
            onChange={handleAlunosChange}
            disabled={!editMode}
          >
            {alunos.map((aluno) => (
              <option key={aluno.id} value={aluno.nome}>
                {aluno.nome}
              </option>
            ))}
          </select>

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                Cancelar
              </button>
              <button className="btn btn-primary" onClick={handleSaveClick}>
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
